using System;
using System.IO;

// PROGRAM: Pembuktian Siklus Hidup IDisposable dan Blok Using
public class DatabaseConnectionSimulator : IDisposable
{
    public string ConnectionId { get; }
    public bool IsOpen { get; private set; }

    public DatabaseConnectionSimulator(string id)
    {
        ConnectionId = id;
        IsOpen = true;
        Console.WriteLine($"[SOCKET OPEN] Koneksi {ConnectionId} berhasil dibuka.");
    }

    public void ExecuteQuery(string sql)
    {
        if (!IsOpen) throw new InvalidOperationException("Koneksi sudah tertutup!");
        Console.WriteLine($"[SQL EXEC] {ConnectionId} -> {sql}");
    }

    public void Dispose()
    {
        if (IsOpen)
        {
            IsOpen = false;
            Console.WriteLine($"[SOCKET CLOSE] Koneksi {ConnectionId} dibersihkan seketika.");
        }
    }
}

public class Program
{
    public static void Main()
    {
        // Simulasi penggunaan scope menggunakan pernyataan 'using'
        using (var db = new DatabaseConnectionSimulator("CONN_POOL_#1"))
        {
            db.ExecuteQuery("SELECT * FROM Customers");
        } // Di baris kurung tutup ini, db.Dispose() otomatis dipanggil!

        Console.WriteLine("Luar blok using: Socket sudah terbukti ditutup dengan aman.");
    }
}

