using System;
using System.Diagnostics;

public class OperationTimer : IDisposable
{
    private readonly string _operationName;
    private readonly Stopwatch _stopwatch;
    private bool _disposed = false;

    public OperationTimer(string operationName)
    {
        _operationName = operationName ?? "Operation";
        _stopwatch = Stopwatch.StartNew();
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;

        _stopwatch.Stop();
        Console.WriteLine($"[COMPLETED] {_operationName} in {_stopwatch.ElapsedMilliseconds} ms");
    }
}

public class Program
{
    public static void Main()
    {
        using (new OperationTimer("DatabaseMigration"))
        {
            System.Threading.Thread.Sleep(50);
        }
    }
}
